50	/// An IR transform that sorts import statements according to specified options.
51	/// Heavily inspired by ESLint's `@perfectionist/sort-imports` rule.
52	/// <https://perfectionist.dev/rules/sort-imports>
53	///
54	/// Transform the given slice of `FormatElement`s by sorting import statements according
55	/// to the specified options. The slice is one chunk of consecutive `ImportDeclaration`s
56	/// as written to the formatter buffer (delimited by the streaming driver in `FormatProgramBody`).
57	///
58	// NOTE: The input `FormatElement`s are already well-formatted.
59	// It means that:
60	// - There is no redundant spaces, no consecutive line breaks, etc...
61	// - The slice does not end with a line break (the inter-statement separator is written
62	//   by the next `entry` call, not as part of the chunk).
63	fn transform<'a>(
64	    elements: &[FormatElement<'a>],
65	    options: &SortImportsOptions,
66	    allocator: &'a Allocator,
67	) -> ArenaVec<'a, FormatElement<'a>> {
68	    // Parse string based groups into our internal representation for performance
69	    let group_matcher = GroupMatcher::new(&options.groups, &options.custom_groups);
70	    let prev_elements: &[FormatElement<'a>] = elements;
71	
72	    // Roughly speaking, sort-imports is a process of swapping lines.
73	    // Therefore, as a preprocessing, group IR elements into line first.
74	    // e.g.
75	    // ```text
76	    // [Text, Space, Text, Line, StartTag, Text, Text, EndTag, Line, ...]
77	    // ```
78	    // ↓↓
79	    // ```text
80	    // [ [Text, Space, Text], [StartTag, Text, Text, EndTag], [...] ]
81	    // ```
82	    //
83	    // This is also meaningful to explicitly handle comment line, empty line,
84	    // and other line with or without import statement.
85	    //
86	    // NOTE: `FormatElement::Line(_)` may not exactly correspond to an actual line break in the output.
87	    // e.g. `LineMode::SoftOrSpace` may be rendered as a space.
88	    //
89	    // And this implementation is based on the following assumptions:
90	    // - Only `Line(Hard|Empty)` is used for joining `Program.body` in the output
91	    // - `Line(Hard|Empty)` does not appear inside an `ImportDeclaration` formatting
92	    //   - If this is the case, we should check `Tag::StartLabelled(JsLabels::ImportDeclaration)`
93	    let mut lines = vec![];
94	    let mut current_line_start = 0;
95	    // Track if we're inside an alignable block comment (identified by `JsLabels::AlignableBlockComment`)
96	    let mut in_alignable_block_comment = false;
97	    // Track if current line is a standalone alignable comment (no import on same line)
98	    let mut is_standalone_alignable_comment = false;
99	    // Track if current line is inside a multiline ImportDeclaration
100	    let mut inside_multiline_import = false;
101	
102	    // All flushed lines terminate with `Hard`.
103	    // The `Line(Empty)` semantic is captured separately as a `SourceLine::Empty` push,
104	    // so we don't propagate `Empty` mode into the line itself.
105	    let build_flush_line = |range, standalone_alignable_comment| {
106	        if standalone_alignable_comment {
107	            SourceLine::CommentOnly(range, LineMode::Hard)
108	        } else {
109	            SourceLine::from_element_range(prev_elements, range, LineMode::Hard)
110	        }
111	    };
112	
113	    for (idx, el) in prev_elements.iter().enumerate() {
114	        // Check for alignable block comment boundaries.
115	        // These comments are split across multiple lines with hard_line_break() between them,
116	        // so we need to track when we're inside one to avoid flushing lines prematurely.
117	        if let FormatElement::Tag(Tag::StartLabelled(id)) = el {
118	            if *id == LabelId::of(JsLabels::AlignableBlockComment) {
119	                in_alignable_block_comment = true;
120	                is_standalone_alignable_comment = true;
121	            } else if *id == LabelId::of(JsLabels::ImportDeclaration) {
122	                inside_multiline_import = true;
123	                // An import on the same line means the comment is attached to it, not standalone
124	                is_standalone_alignable_comment = false;
125	            }
126	        } else if matches!(el, FormatElement::Tag(Tag::EndLabelled)) {
127	            // EndLabelled doesn't carry the label ID, but since AlignableBlockComment
128	            // doesn't nest with other labels in practice, we can safely reset here.
129	            if in_alignable_block_comment {
130	                in_alignable_block_comment = false;
131	            } else if inside_multiline_import {
132	                // I'm not sure if ImportDeclaration will nest with other labels,
133	                // but this should be enough for now.
134	                inside_multiline_import = false;
135	            }
136	        }
137	
138	        if let FormatElement::Line(mode) = el
139	            && matches!(mode, LineMode::Empty | LineMode::Hard)
140	        {
141	            // If we're inside an alignable block comment, don't flush the line yet.
142	            // Wait until the comment is closed so the entire comment is treated as one line.
143	            if in_alignable_block_comment {
144	                continue;
145	            }
146	
147	            // If the linebreak falls within the body of a multiline ImportDeclaration,
148	            // don't flush the line. e.g.
149	            // ```text
150	            // import React {
151	            //   useState,
152	            //   // this is a comment followed by a FormatElement::Line(LineMode::Hard)
153	            //   useEffect,
154	            // } from 'react';
155	            // ```
156	            if inside_multiline_import {
157	                continue;
158	            }
159	
160	            // Flush current line
161	            if current_line_start < idx {
162	                lines.push(build_flush_line(
163	                    current_line_start..idx,
164	                    is_standalone_alignable_comment,
165	                ));
166	            }
