65	/// Case-insensitive ASCII string comparison (no allocation).
66	fn cmp_ascii_case_insensitive(a: &str, b: &str) -> std::cmp::Ordering {
67	    for (ca, cb) in a.bytes().zip(b.bytes()) {
68	        let ord = ca.to_ascii_lowercase().cmp(&cb.to_ascii_lowercase());
69	        if ord != std::cmp::Ordering::Equal {
70	            return ord;
71	        }
72	    }
73	    a.len().cmp(&b.len())
74	}
