113	/// Collect a run of consecutive `ImportDeclaration`s from `stmts_iter`, format them using `join`,
114	/// then sort them in place.
115	///
116	/// Returns the next statement after the run of `ImportDeclaration`s, or `None` if there are no more statements.
117	///
118	/// The caller must already have verified that `sort_imports` option is enabled.
119	///
120	/// # Panics
121	/// Panics if `sort_imports` option is not enabled.
122	//
123	// `#[cold]` because most statements aren't `ImportDeclaration`s.
124	// Also, when there *are* lots of `ImportDeclaration`s, they tend to all be grouped together.
125	// This function consumes the whole run, so is unlikely to be called more than once, even in files with lots of imports.
126	#[cold]
127	fn format_import_decls_with_sort<'a, 'iter>(
128	    stmt: &AstNode<'a, Statement<'a>>,
129	    stmts_iter: &mut impl Iterator<Item = &'iter AstNode<'a, Statement<'a>>>,
130	    join: &mut JoinNodesBuilder<'_, '_, 'a, Line>,
131	) -> Option<&'iter AstNode<'a, Statement<'a>>> {
132	    // Output inter-statement separator separately, so `chunk_start` points
133	    // to start of IR for the `ImportDeclaration` itself
134	    join.separator_no_entry(stmt.span());
135	    let chunk_start = join.fmt().elements().len();
136	
137	    // Output first `ImportDeclaration`
138	    join.entry_no_separator(stmt);
139	
140	    // The first import was already written above, so start the count at 1.
141	    // A suppressed `ImportDeclaration` ends the run:
142	    // its verbatim IR has no `JsLabels::ImportDeclaration` label, so the sort transform can't see it as an import.
143	    let mut count = 1;
144	    let mut next_stmt = None;
145	    for stmt in stmts_iter {
146	        if let Statement::ImportDeclaration(decl) = stmt.as_ref() {
147	            if is_import_suppressed(stmt, join.fmt()) {
148	                next_stmt = Some(stmt);
149	                break;
150	            }
151	            join.entry(decl.span, stmt);
152	            count += 1;
153	        } else {
154	            next_stmt = Some(stmt);
155	            break;
156	        }
157	    }
158	
159	    // A single-import run is already in order, so skip the transform.
160	    if count >= 2 {
161	        sort_imports_chunk(join.fmt_mut(), chunk_start);
162	    }
163	
164	    next_stmt
165	}
