use oxc_allocator::Allocator;
use oxc_formatter::{
    FormatOptions, Formatter, JsdocOptions, SortImportsOptions, get_parse_options,
};
use oxc_parser::Parser;
use oxc_span::SourceType;

fn run(label: &str, source_text: &str) {
    println!("===== {label} =====");
    let source_type = SourceType::mjs();
    let allocator = Allocator::new();
    let ret = Parser::new(&allocator, source_text, source_type)
        .with_options(get_parse_options())
        .parse();

    let options = FormatOptions {
        sort_imports: Some(SortImportsOptions::default()),
        jsdoc: Some(JsdocOptions::default()),
        ..Default::default()
    };
    let formatter = Formatter::new(&allocator, options);
    let formatted = formatter.format(&ret.program);
    let code = formatted.print().unwrap().into_code();
    println!("{code}");
    println!("-----------------------");
}

fn main() {
    run(
        "single-line jsdoc before imports",
        "/** foo bar */\nimport z from \"z\";\nimport a from \"a\";\n",
    );
    run(
        "multi-line jsdoc before imports",
        "/**\n * foo bar\n * @see something\n */\nimport z from \"z\";\nimport a from \"a\";\n",
    );
    run_sort_only(
        "trailing comment after last import (sort only)",
        "import z from \"z\";\nimport a from \"a\";\n// trailing comment\n",
    );
    run_sort_only(
        "trailing block comment after last import (sort only)",
        "import z from \"z\";\nimport a from \"a\";\n/* trailing */\n",
    );
}

