/// Split off the trailing run of "own-line" line-suffix regions from the end of a chunk.
///
/// Returns `(body, trailing_line_suffix)` where `body` is the chunk with the trailing
/// own-line comment(s) removed and `trailing_line_suffix` is the peeled-off tail (empty
/// when there is none).
///
/// A comment sitting on its own line after the last import is emitted as deferred
/// line-suffix content (`StartLineSuffix … Line(Hard) … EndLineSuffix`). Same-line trailing
/// comments (`import a; // c`) are also line suffixes but carry no inner line break; those
/// must stay attached to their import, so they are left in `body`.
fn split_trailing_line_suffix<'a, 'e>(
    elements: &'e [FormatElement<'a>],
) -> (&'e [FormatElement<'a>], &'e [FormatElement<'a>]) {
    let mut split = elements.len();
    while split > 0 {
        // The tail must be a complete line-suffix region.
        if !matches!(elements[split - 1], FormatElement::Tag(Tag::EndLineSuffix)) {
            break;
        }
        // Walk back to the matching `StartLineSuffix`. Line suffixes don't nest in practice,
        // but track depth defensively in case they ever do.
        let mut depth = 0_usize;
        let mut region_start = None;
        for i in (0..split).rev() {
            match &elements[i] {
                FormatElement::Tag(Tag::EndLineSuffix) => depth += 1,
                FormatElement::Tag(Tag::StartLineSuffix) => {
                    depth -= 1;
                    if depth == 0 {
                        region_start = Some(i);
                        break;
                    }
                }
                _ => {}
            }
        }
        let Some(region_start) = region_start else { break };
        // Only hoist own-line comments (the region carries its own line break).
        // Same-line trailing comments must remain glued to their import line.
        let is_own_line = elements[region_start..split]
            .iter()
            .any(|el| matches!(el, FormatElement::Line(LineMode::Hard | LineMode::Empty)));
        if !is_own_line {
            break;
        }
        split = region_start;
    }
    (&elements[..split], &elements[split..])
